import { computed, reactive, ref } from 'vue'

/** A rule for one field: the message to show when the value is wrong, or nothing when it is right. */
export type Rule<V extends Record<string, unknown>> = (value: V[keyof V], values: V) => string | undefined

/**
 * A form's values, its errors and its submit (the Form item). An error shows once its field has been left or the form
 * submitted, never while the first value is still being typed; after that it updates as the value changes. `submit`
 * checks every rule and runs `send` only when all pass, holding `sending` while it runs; a thrown Error's message
 * becomes the form's `failure`.
 */
export function useForm<V extends Record<string, unknown>>(initial: V, rules: Partial<Record<keyof V, Rule<V>>>) {
  const values = reactive({ ...initial }) as V
  const touched = reactive<Record<string, boolean>>({})
  const tried = ref(false)
  const sending = ref(false)
  const failure = ref('')

  const all = computed(() => {
    const out: Partial<Record<keyof V, string>> = {}
    for (const key of Object.keys(rules) as Array<keyof V>) {
      const message = rules[key]?.(values[key], values)
      if (message) out[key] = message
    }
    return out
  })
  /** The errors to show now. */
  const errors = computed(() => {
    const out: Partial<Record<keyof V, string>> = {}
    for (const key of Object.keys(all.value) as Array<keyof V>) if (tried.value || touched[String(key)]) out[key] = all.value[key]
    return out
  })
  const valid = computed(() => Object.keys(all.value).length === 0)

  function touch(key: keyof V) {
    touched[String(key)] = true
  }
  async function submit(send: (values: V) => Promise<void> | void) {
    tried.value = true
    failure.value = ''
    if (!valid.value || sending.value) return false
    sending.value = true
    try {
      await send(values)
      return true
    }
    catch (error) {
      failure.value = error instanceof Error ? error.message : 'Something went wrong. Try again.'
      return false
    }
    finally {
      sending.value = false
    }
  }
  function reset() {
    Object.assign(values, initial)
    for (const key of Object.keys(touched)) delete touched[key]
    tried.value = false
    failure.value = ''
  }

  return { values, errors, valid, sending, failure, touch, submit, reset }
}

'use client'
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react'

// A form in the console's grammar (new, composed from Field, Input and Button): fields stacked 16px apart, each a Field
// with its label over it and its hint or error under it; a failure from the server in a red-wash box above the actions;
// the actions at the end, the main one last. It never validates as the first value is typed: useForm shows an error
// once its field is left or the form is sent, and on a send with errors focus moves to the first field that is wrong.
// The browser's own bubbles are off (noValidate); Enter in a field sends it. Vue's #actions slot is `actions`.
export interface FormProps { failure?: string, label?: string, onSubmit?: () => void, actions?: ReactNode, children?: ReactNode, className?: string }

export function Form({ failure, label, onSubmit, actions, children, className }: FormProps) {
  const form = useRef<HTMLFormElement | null>(null)
  // Vue moves focus after the next render (nextTick), once the errors the submit raised are drawn.
  const [sent, setSent] = useState(0)
  useEffect(() => {
    if (sent) form.current?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus()
  }, [sent])
  function send(event: FormEvent) {
    event.preventDefault()
    onSubmit?.()
    setSent(n => n + 1)
  }
  return (
    <form data-ds="form" ref={form} className={className ? `flex flex-col gap-4 ${className}` : 'flex flex-col gap-4'} noValidate aria-label={label} onSubmit={send}>
      {children}
      {failure && (
        <p className="flex items-start gap-2 border border-transparent bg-surface-danger px-3 py-2 type-meta text-fg-danger" role="alert">
          <span className="mt-1.5 size-1 shrink-0 bg-edge-accent" aria-hidden="true" />{failure}
        </p>
      )}
      {actions && <div className="flex flex-wrap items-center justify-end gap-2 pt-2">{actions}</div>}
    </form>
  )
}

export default Form

'use client'
import { useCallback, useRef, useState } from 'react'

/** A rule for one field: the message to show when the value is wrong, or nothing when it is right. */
export type Rule<V extends Record<string, unknown>> = (value: V[keyof V], values: V) => string | undefined

/**
 * A form's values, its errors and its submit (the Form item). An error shows once its field has been left or the form
 * submitted, never while the first value is still being typed; after that it updates as the value changes. `submit`
 * checks every rule and runs `send` only when all pass, holding `sending` while it runs; a thrown Error's message
 * becomes the form's `failure`. Vue's reactive `values` (written by v-model) is `values` with `set(key, value)`.
 */
export function useForm<V extends Record<string, unknown>>(initial: V, rules: Partial<Record<keyof V, Rule<V>>>) {
  const [values, setValues] = useState<V>({ ...initial })
  const [touched, setTouched] = useState<Record<string, boolean>>({})
  const [tried, setTried] = useState(false)
  const [sending, setSending] = useState(false)
  const [failure, setFailure] = useState('')
  // The latest values and sending, for a submit called from a stale closure.
  const latest = useRef(values)
  latest.current = values
  const busy = useRef(false)
  const first = useRef(initial)
  const rulesRef = useRef(rules)
  rulesRef.current = rules

  const check = (v: V) => {
    const out: Partial<Record<keyof V, string>> = {}
    for (const key of Object.keys(rulesRef.current) as Array<keyof V>) {
      const message = rulesRef.current[key]?.(v[key], v)
      if (message) out[key] = message
    }
    return out
  }
  const all = check(values)
  /** The errors to show now. */
  const errors: Partial<Record<keyof V, string>> = {}
  for (const key of Object.keys(all) as Array<keyof V>) if (tried || touched[String(key)]) errors[key] = all[key]
  const valid = Object.keys(all).length === 0

  const set = useCallback(<K extends keyof V>(key: K, value: V[K]) => {
    setValues(v => ({ ...v, [key]: value }))
  }, [])
  const touch = useCallback((key: keyof V) => {
    setTouched(t => ({ ...t, [String(key)]: true }))
  }, [])
  const submit = useCallback(async (send: (values: V) => Promise<void> | void) => {
    setTried(true)
    setFailure('')
    if (Object.keys(check(latest.current)).length || busy.current) return false
    busy.current = true
    setSending(true)
    try {
      await send(latest.current)
      return true
    }
    catch (error) {
      setFailure(error instanceof Error ? error.message : 'Something went wrong. Try again.')
      return false
    }
    finally {
      busy.current = false
      setSending(false)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  const reset = useCallback(() => {
    setValues({ ...first.current })
    setTouched({})
    setTried(false)
    setFailure('')
  }, [])

  return { values, set, errors, valid, sending, failure, touch, submit, reset }
}

